require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/layout.php'; if($u=user()) go($u['role'].'/'); $register=isset($_GET['register']); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ check_csrf(); try{ $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??''; if($register){ if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10||!trim($_POST['name']??'')) throw new RuntimeException('Provide your name, valid email and password with at least 10 characters.'); $db->beginTransaction(); q("INSERT INTO users(name,email,password,role,phone) VALUES(?,?,?,'customer',?)",[trim($_POST['name']),$email,password_hash($password,PASSWORD_DEFAULT),substr($_POST['phone']??'',0,30)]); $uid=(int)$db->lastInsertId(); q('INSERT INTO customers VALUES(?)',[$uid]); $db->commit(); } else { if(($_SESSION['login_attempts']??0)>=8 && time()-($_SESSION['last_attempt']??0)<300) throw new RuntimeException('Too many attempts. Try again in five minutes.'); $found=one('SELECT * FROM users WHERE email=?',[$email]); if(!$found || !password_verify($password,$found['password'])){$_SESSION['login_attempts']=($_SESSION['login_attempts']??0)+1; $_SESSION['last_attempt']=time(); throw new RuntimeException('Email or password is incorrect.');} $uid=(int)$found['id']; } session_regenerate_id(true); $_SESSION['uid']=$uid; unset($_SESSION['login_attempts']); go(user()['role'].'/'); }catch(Throwable $ex){ if($db->inTransaction())$db->rollBack(); $error=$ex instanceof PDOException?'This account could not be created. The email may already be registered.':$ex->getMessage(); }}
